<?php
require __DIR__.'/ui.php';role(['admin','gerente','vendedor']);$p=db();
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$p->prepare("INSERT INTO quotes(number,customer_id,description,amount,valid_days,status,notes)VALUES(?,?,?,?,?,'Em aberto',?)")->execute([next_number('ORC-','quotes'),$_POST['customer_id']?:null,$_POST['description'],$_POST['amount'],$_POST['valid_days'],$_POST['notes']]);go('quotes.php');}
if(isset($_GET['approve'])){$p->prepare("UPDATE quotes SET status='Aprovado' WHERE id=?")->execute([(int)$_GET['approve']]);go('quotes.php');}$customers=$p->query("SELECT id,name FROM customers ORDER BY name")->fetchAll();$rows=$p->query("SELECT q.*,c.name customer FROM quotes q LEFT JOIN customers c ON c.id=q.customer_id ORDER BY q.id DESC")->fetchAll();page_head('Orçamentos');?>
<div class="grid g2"><div class="card"><h2>Novo orçamento</h2><form method="post"><?=csrf_field()?><label>Cliente</label><select name="customer_id"><option value="">Consumidor</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select><label>Descrição</label><textarea name="description"></textarea><div class="grid g2"><div><label>Valor</label><input type="number" step=".01" name="amount"></div><div><label>Validade dias</label><input type="number" name="valid_days" value="7"></div></div><label>Observações</label><textarea name="notes"></textarea><button class="primary">Salvar</button></form></div><div class="card"><h2>Resumo</h2><p>Abertos: <?=count(array_filter($rows,fn($x)=>$x['status']==='Em aberto'))?></p><p>Aprovados: <?=count(array_filter($rows,fn($x)=>$x['status']==='Aprovado'))?></p></div></div>
<div class="card"><div class="table"><table><tr><th>Nº</th><th>Cliente</th><th>Descrição</th><th>Valor</th><th>Status</th><th></th></tr><?php foreach($rows as $x):?><tr><td><?=e($x['number'])?></td><td><?=e($x['customer']?:'Consumidor')?></td><td><?=e($x['description'])?></td><td><?=money($x['amount'])?></td><td><?=e($x['status'])?></td><td><?php if($x['status']!=='Aprovado'):?><a class="btn green" href="?approve=<?=$x['id']?>">Aprovar</a><?php endif;?></td></tr><?php endforeach;?></table></div></div><?php page_foot();?>